ClipboardPage newAssignPage = tools.findPage("newAssignPage");
ClipboardProperty pyAssignActions = newAssignPage.getIfPresent("pyAssignActions");
String flowActionType = "";
if (pyAssignActions != null) {
	java.util.Iterator iter = pyAssignActions.iterator();
	while (iter.hasNext()) {
		ClipboardProperty assignAction = (ClipboardProperty)iter.next();
		ClipboardPage pgAction = assignAction.getPageValue();
		if (tools.getParamValue("TaskStatus").equals(pgAction.getString(".pyActionName"))) {
			flowActionType = pgAction.getString(".pyActionType");
			break;
		}
	}
}

String strInterestPage = "";
/*
 * If action is local stage/case action, always set interest page to the primary page. 
 * The primary page is also the default if pyInterestPage is blank.
 */
if (flowActionType.equals("LocalCase") || newAssignPage.getString("pyInterestPage").equals("")) {
	strInterestPage = myStepPage.getName();
} else {
	strInterestPage = newAssignPage.getString("pyInterestPage");
}
tools.putParamValue("InterestPage", strInterestPage);

String strFlowName = tools.findPage("newAssignPage").getString("pxFlowName");
if(!strFlowName.equals("")){
ClipboardPage pg_pyWorkPage = tools.getPrimaryPage();
ClipboardProperty cp_pxFlow = pg_pyWorkPage.getProperty("pxFlow("+strFlowName+")");
if(!cp_pxFlow.isEmpty()){
    ClipboardPage pg_pxFlow = cp_pxFlow.getPageValue();
    defErrors=pg_pxFlow.getString("pyDeferErrors");
  }
}

ClipboardPage pgAutoTestCase = tools.findPage("pyAutoTestCase");
String strRunActivity = "true";
if (pgAutoTestCase != null) { //not possible with precondition, but just in case
	strRunActivity = pgAutoTestCase.getString(".pyRunActivity");
}
if (strRunActivity.equals("false")) { //so we only do this upon entering inputs and not displaying differences
//get the step for which we need to show inputs (the step will always be 1 more thean the size of the 
// MultiStepDifferences page in the ResultRecord page
ClipboardPage resPage = tools.findPage("ResultRecord");
int iStep = 0;
if (resPage != null) {
	ClipboardProperty multiStepDiffs = resPage.getIfPresent("pyMultiStepDifferences");
	if (multiStepDiffs != null) {
		iStep = multiStepDiffs.size();
		//iStep++;
	}
}
iStep++;
Integer IStep = new Integer(iStep);
String strTopPage = "pyAutoTestCase";
String strInputPage = ".pyInput(" + IStep.toString() + ")";
String strStepPage = strTopPage + strInputPage + ".pyUserInputs";

ClipboardPage pgStepPage = tools.findPage(strStepPage);
if(pgStepPage != null) {
	ClipboardProperty cpInputs = pgStepPage.getProperty(".pyInput");
	java.util.Iterator itInputs = cpInputs.iterator();
	while(itInputs.hasNext()) {
		ClipboardProperty cpInput = (ClipboardProperty)itInputs.next();
		ClipboardPage pgInput = cpInput.getPageValue();

		//get the page and property names from the pyInputProperty
		String strInputName = pgInput.getProperty("pyInputProperty").getStringValue();
		String strPageName = strInputName.substring(0,strInputName.lastIndexOf("."));
		String strTopPageName = strInputName.substring(0,strInputName.indexOf("."));
		String strEmbeddedPageName = "";
		if (strInputName.indexOf(".") != strInputName.lastIndexOf("."))
			strEmbeddedPageName = strInputName.substring(strInputName.indexOf("."),strInputName.lastIndexOf("."));
		String strPropName = strInputName.substring(strInputName.lastIndexOf(".") + 1);

		//---****** start: New code for handling overwriting of inputs ********------
		// Get the user entered input as a default
		String strInputValue = pgInput.getProperty("pyInputValue").getStringValue();

		// Get the stored page (ex: pyAutoTestCase.pyInput(N).pyInitialPages("pyWorkPage") )
		String strStoredPage = ""; 
		if (strEmbeddedPageName.equals("")) {
			strStoredPage = strTopPage + strInputPage + ".pyInitialPages(" + strTopPageName + ")";
		} else {
			strStoredPage = strTopPage + strInputPage + ".pyInitialPages(" + strTopPageName + ")" + strEmbeddedPageName;
		}
		ClipboardPage pgStoredPage = tools.findPage(strStoredPage);

		// if the stored page can be found, get the stored input value (sometimes different than the user entered one due to formatting)
		if (pgStoredPage != null) {
			strInputValue = pgStoredPage.getString(strPropName);
		}

		ClipboardPage pgInputPage = tools.findPage(strPageName);
		if(pgInputPage!=null) {
			if(!pgInputPage.getString(strPropName).equals(strInputValue)) {
				pgInputPage.putString(strPropName, strInputValue);
			}
		}
		//---****** end: New code for handling overwriting of inputs ********------

	}
}
}
